"use strict";
let kept = null;
exports.useSink = (sink) => sink.take(2) + sink.take(3);
exports.useHolder = (holder) => holder.sink.take(holder.label.length);
exports.useList = (list) => list.reduce((n, sink) => n + sink.take(1), 0);
exports.useTable = (table) => table.get("k").take(8);
exports.useNest = (nest) => nest.inner.take(9);
exports.callBack = (make) => make().take(5);
exports.keep = (sink) => {
  kept = sink;
};
exports.useKept = () => kept.take(6);
exports.shape = (value) =>
  typeof value.take + "/" + ("take" in value) + "/" + Object.keys(value).join(",");
exports.extra = (value) =>
  typeof value.take + "/" + (typeof value.extra === "function" ? value.extra() : "none");
exports.sameTake = (a, b) => a.take === b.take && a.take === a.take;
exports.kinds = async (value) => {
  const out = [];
  for (const k of ["plain", "later", "each", "opt", "over", "stat", "hidden", "value"])
    out.push(k + ":" + typeof value[k]);
  out.push("later=" + (await value.later(2)));
  out.push("opt=" + value.opt() + "," + value.opt(3));
  out.push("each=" + value.each((n) => n + 1));
  out.push("over=" + value.over(1) + "," + value.over("s"));
  out.push("value=" + value.value);
  return out.join(" ");
};
